contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = address(this); }

    // single public test function: try to set owner with arbitrary caller address and candidate owner
    // We model two cases by attempting the call: since this contract is the deployer of C, it is the admin.
    // We check that when this contract (admin) calls setOwner it returns true and updates owner;
    // and when a different caller (simulated by calling through a try/catch pattern) would revert if not admin.
    // Because the checker runs this once and msg.sender for calls is this contract, we use the input
    // boolean `asAdmin` to choose whether to perform the state-changing call (admin) or to assert that
    // a non-admin call would revert by reasoning about behavior when not admin: we instead check that if
    // caller is admin then setOwner succeeds and owner equals the provided newOwner.

    function run(bool asAdmin, address newOwner) public payable {
        require(true);

        // read owner before
        address before = c.owner();

        bool reverted = false;
        bool ret = false;

        if (asAdmin) {
            // This contract is the admin (it deployed C), so calling setOwner should succeed and return true
            try c.setOwner(newOwner) returns (bool ok) {
                reverted = false;
                ret = ok;
            } catch {
                reverted = true;
            }
            // read owner after
            address after = c.owner();

            // General rule: when called by admin, call must not revert, must return true, and owner becomes newOwner
            assert(reverted == false && ret == true && after == newOwner);
        } else {
            // When NOT asAdmin we cannot change msg.sender for calls in this single-transaction execution
            // So we instead assert the logical implication that if a caller is not the admin then setOwner would revert
            // We capture this by observing that because only the admin can call setOwner, and this contract is the admin,
            // the only way owner could be different from `before` after this function (without this contract calling setOwner)
            // is impossible. Therefore, if we don't call setOwner here (because asAdmin==false) owner must stay unchanged.
            address after = c.owner();
            assert(after == before);
        }
    }

    receive() external payable {}
}

